132: function describeSlice(startAngle: number, endAngle: number): string {
133:   const start = pointOnCircle(startAngle);
134:   const end = pointOnCircle(endAngle);
135:   const sweepAngle = endAngle - startAngle;
136: 
137:   if (sweepAngle >= 359.999) {
138:     const opposite = pointOnCircle(startAngle + 180);
139:     return [
140:       `M ${CHART_CENTER} ${CHART_CENTER}`,
141:       `L ${start.x} ${start.y}`,
142:       `A ${CHART_RADIUS} ${CHART_RADIUS} 0 1 1 ${opposite.x} ${opposite.y}`,
143:       `A ${CHART_RADIUS} ${CHART_RADIUS} 0 1 1 ${start.x} ${start.y}`,
144:       'Z',
145:     ].join(' ');
146:   }
147: 
148:   const largeArcFlag = sweepAngle > 180 ? 1 : 0;
149:   return [
150:     `M ${CHART_CENTER} ${CHART_CENTER}`,
151:     `L ${start.x} ${start.y}`,
152:     `A ${CHART_RADIUS} ${CHART_RADIUS} 0 ${largeArcFlag} 1 ${end.x} ${end.y}`,
153:     'Z',
154:   ].join(' ');
155: }
156: 
157: function pointOnCircle(angle: number): { x: number; y: number } {
158:   const radians = (angle * Math.PI) / 180;
159:   return {
160:     x: CHART_CENTER + CHART_RADIUS * Math.cos(radians),
161:     y: CHART_CENTER + CHART_RADIUS * Math.sin(radians),
162:   };
163: }
164: 
165: function formatPercentage(value: number, total: number): string {
166:   const percentage = (value / total) * 100;
167:   if (percentage < 0.1) return '<0.1%';
168:   return `${percentage < 1 ? percentage.toFixed(1) : Math.round(percentage)}%`;
169: }

