509:     private func startStreamConsumption(
510:         _ stream: AsyncThrowingStream<AgentStreamEvent, Error>,
511:         sessionId: String,
512:         assistantMessageId: String,
513:         initialRunId: String,
514:         shouldGenerateTitle: Bool
515:     ) {
516:         cancelActiveStreamLocally()
517:         isStreaming = true
518:         isStopping = false
519:         streamingRunId = initialRunId
520:         elapsedSeconds = 0
521: 
522:         timerTask = Task { [weak self] in
523:             while !Task.isCancelled {
524:                 try? await Task.sleep(for: .seconds(1))
525:                 guard !Task.isCancelled, let self else { return }
526:                 self.elapsedSeconds += 1
527:             }
528:         }
529: 
530:         streamTask = Task { [weak self] in
531:             guard let self else { return }
532:             var terminatedExplicitly = false
533:             do {
534:                 for try await event in stream {
535:                     guard !Task.isCancelled else { return }
536:                     switch event {
537:                     case .runStarted(let serverRunId):
538:                         if !serverRunId.isEmpty {
539:                             self.streamingRunId = serverRunId
540:                         }
541: 
542:                     case .thinking(let chunk):
543:                         self.mutateMessage(id: assistantMessageId) {
544:                             AgentTimelineBuilder.appendThinking($0, chunk: chunk)
545:                         }
546: 
547:                     case .text(let chunk):
548:                         self.mutateMessage(id: assistantMessageId) {
549:                             AgentTimelineBuilder.appendText($0, chunk: chunk)
550:                         }
551: 
552:                     case .toolCall(let toolCallId, let toolName, let command):
553:                         self.mutateMessage(id: assistantMessageId) {
554:                             AgentTimelineBuilder.upsertToolCall(
555:                                 $0,
556:                                 toolCallId: toolCallId,
557:                                 toolName: toolName,
558:                                 command: command
559:                             )
560:                         }
561: 
562:                     case .toolResult(let toolCallId, _, let result, let status):
563:                         self.mutateMessage(id: assistantMessageId) {
564:                             AgentTimelineBuilder.applyToolResult(
565:                                 $0,
566:                                 toolCallId: toolCallId,
567:                                 result: result,
568:                                 status: status
569:                             )
570:                         }
571: 
572:                     case .routingNotice(let notice):
573:                         self.routingNotice = notice
574: 
575:                     case .subagent(let progress):
576:                         self.upsertSubagentNotice(progress)
577: 
578:                     case .permissionRequired(let approval):
579:                         terminatedExplicitly = true
580:                         self.finishStreamingFlags(
581:                             assistantMessageId: assistantMessageId,
582:                             status: nil
583:                         )
584:                         self.setPendingApproval(approval)
585: 
586:                     case .done:
587:                         terminatedExplicitly = true
588:                         self.finishStreamingFlags(
589:                             assistantMessageId: assistantMessageId,
590:                             status: .completed
591:                         )
592:                         await self.syncSessionAfterStream(
593:                             sessionId: sessionId,
594:                             shouldGenerateTitle: shouldGenerateTitle
595:                         )
596: 
597:                     case .cancelled:
598:                         terminatedExplicitly = true
599:                         self.finishStreamingFlags(
600:                             assistantMessageId: assistantMessageId,
601:                             status: .cancelled
602:                         )
603:                         await self.syncSessionAfterStream(
604:                             sessionId: sessionId,
605:                             shouldGenerateTitle: false
606:                         )
607: 
608:                     case .error(let message):
609:                         terminatedExplicitly = true
610:                         self.finishStreamingFlags(
611:                             assistantMessageId: assistantMessageId,
612:                             status: .failed
613:                         )
614:                         self.errorMessage = message
615:                     }
616:                 }
617:                 if !terminatedExplicitly {
618:                     self.finishStreamingFlags(
619:                         assistantMessageId: assistantMessageId,
620:                         status: .completed
621:                     )
622:                 }
623:             } catch is CancellationError {
624:                 self.finishStreamingFlags(assistantMessageId: assistantMessageId, status: .cancelled)
625:             } catch {
626:                 self.finishStreamingFlags(assistantMessageId: assistantMessageId, status: .failed)
627:                 self.errorMessage = Self.userFacingError(error)
628:             }
629:         }
630:     }
