3: /** 一次或一轮模型输入的本地估算构成；只有 actual Input 来自供应商。 */
4: public record InputTokenBreakdown(
5:         long systemPromptTokens,
6:         long historyTokens,
7:         long currentUserTokens,
8:         long toolSchemaTokens,
9:         long toolResultTokens,
10:         long profileContextTokens,
11:         long memoryRecallTokens,
12:         long ragContextTokens,
13:         long otherTokens
14: ) {
15: 
16:     public InputTokenBreakdown {
17:         systemPromptTokens = nonNegative(systemPromptTokens);
18:         historyTokens = nonNegative(historyTokens);
19:         currentUserTokens = nonNegative(currentUserTokens);
20:         toolSchemaTokens = nonNegative(toolSchemaTokens);
21:         toolResultTokens = nonNegative(toolResultTokens);
22:         profileContextTokens = nonNegative(profileContextTokens);
23:         memoryRecallTokens = nonNegative(memoryRecallTokens);
24:         ragContextTokens = nonNegative(ragContextTokens);
25:         otherTokens = nonNegative(otherTokens);
26:     }
27: 
28:     public static InputTokenBreakdown empty() {
29:         return new InputTokenBreakdown(0, 0, 0, 0, 0, 0, 0, 0, 0);
30:     }
31: 
32:     /** 不含 Provider 协议差值的可解释输入估算。 */
33:     public long estimatedTokens() {
34:         return systemPromptTokens + historyTokens + currentUserTokens + toolSchemaTokens
35:                 + toolResultTokens + profileContextTokens + memoryRecallTokens + ragContextTokens;
36:     }
37: 
38:     public InputTokenBreakdown withOtherTokens(long value) {
39:         return new InputTokenBreakdown(
40:                 systemPromptTokens, historyTokens, currentUserTokens, toolSchemaTokens,
41:                 toolResultTokens, profileContextTokens, memoryRecallTokens, ragContextTokens, value);
42:     }
43: 
44:     public InputTokenBreakdown plus(InputTokenBreakdown other) {
45:         if (other == null) return this;
46:         return new InputTokenBreakdown(
47:                 systemPromptTokens + other.systemPromptTokens,
48:                 historyTokens + other.historyTokens,
49:                 currentUserTokens + other.currentUserTokens,
50:                 toolSchemaTokens + other.toolSchemaTokens,
51:                 toolResultTokens + other.toolResultTokens,
52:                 profileContextTokens + other.profileContextTokens,
53:                 memoryRecallTokens + other.memoryRecallTokens,
54:                 ragContextTokens + other.ragContextTokens,
55:                 otherTokens + other.otherTokens);
56:     }
57: 
58:     private static long nonNegative(long value) {
59:         return Math.max(0, value);
60:     }
