21:     static func group(
22:         _ sessions: [AgentSessionSummary],
23:         now: Date = Date(),
24:         calendar: Calendar = .current
25:     ) -> [(group: AgentSessionTimeGroup, items: [AgentSessionSummary])] {
26:         let startOfToday = calendar.startOfDay(for: now)
27:         let startOfYesterday = calendar.date(byAdding: .day, value: -1, to: startOfToday) ?? startOfToday
28:         let startOf7DaysAgo = calendar.date(byAdding: .day, value: -7, to: startOfToday) ?? startOfToday
29: 
30:         var buckets: [AgentSessionTimeGroup: [AgentSessionSummary]] = [:]
31:         for session in sessions {
32:             let date = session.updatedAt
33:             let bucket: AgentSessionTimeGroup
34:             if date >= startOfToday {
35:                 bucket = .today
36:             } else if date >= startOfYesterday {
37:                 bucket = .yesterday
38:             } else if date >= startOf7DaysAgo {
39:                 bucket = .last7Days
40:             } else {
41:                 bucket = .older
42:             }
43:             buckets[bucket, default: []].append(session)
44:         }
45: 
46:         return AgentSessionTimeGroup.allCases.compactMap { group in
47:             guard let items = buckets[group], !items.isEmpty else { return nil }
48:             return (group: group, items: items)
49:         }
50:     }
51: }
