127:     private List<String> normalizedReferenceIds(List<String> values) {
128:         if (values == null || values.isEmpty()) return List.of();
129:         LinkedHashSet<String> ids = new LinkedHashSet<>();
130:         values.forEach(value -> {
131:             if (value != null && !value.isBlank()) ids.add(value.strip());
