4: struct SSELineParser {
5:     private var lineBuffer: [UInt8] = []
6:     private var currentEventName: String?
7:     private var dataLines: [String] = []
8:     private let decoder: JSONDecoder
9: 
10:     init(decoder: JSONDecoder = APIClient.decoder) {
11:         self.decoder = decoder
12:     }
13: 
14:     mutating func feed(_ byte: UInt8) -> AgentStreamEvent? {
15:         if byte == 0x0A { // '\n'
16:             if lineBuffer.last == 0x0D { // '\r'
17:                 lineBuffer.removeLast()
18:             }
19:             let line = String(decoding: lineBuffer, as: UTF8.self)
20:             lineBuffer.removeAll(keepingCapacity: true)
21:             return processLine(line)
22:         }
23:         lineBuffer.append(byte)
24:         return nil
25:     }
26: 
27:     mutating func finish() -> AgentStreamEvent? {
28:         if !lineBuffer.isEmpty {
29:             if lineBuffer.last == 0x0D {
30:                 lineBuffer.removeLast()
31:             }
32:             let line = String(decoding: lineBuffer, as: UTF8.self)
33:             lineBuffer.removeAll(keepingCapacity: false)
34:             if let event = processLine(line) {
35:                 return event
36:             }
37:         }
38:         return flushEvent()
39:     }
40: 
41:     private mutating func processLine(_ line: String) -> AgentStreamEvent? {
42:         if line.isEmpty {
43:             return flushEvent()
44:         }
45:         if line.hasPrefix(":") {
46:             return nil
47:         }
48:         if line.hasPrefix("event:") {
49:             let value = line.dropFirst(6).trimmingCharacters(in: .whitespaces)
50:             currentEventName = value.isEmpty ? nil : value
51:             return nil
52:         }
53:         if line.hasPrefix("data:") {
54:             dataLines.append(String(line.dropFirst(5)))
55:             return nil
56:         }
57:         return nil
58:     }
59: 
60:     private mutating func flushEvent() -> AgentStreamEvent? {
61:         guard currentEventName != nil || !dataLines.isEmpty else {
62:             return nil
63:         }
64:         let eventName = currentEventName ?? "message"
65:         let payload = dataLines.joined(separator: "\n")
66:         currentEventName = nil
67:         dataLines.removeAll(keepingCapacity: true)
68:         return decodeEvent(name: eventName, dataString: payload)
69:     }
70: 
71:     private func decodeEvent(name: String, dataString: String) -> AgentStreamEvent? {
72:         switch name {
73:         case "run_started":
74:             if let dto = decodeJSON(RunStartedDTO.self, from: dataString) {
75:                 return .runStarted(runId: dto.runId ?? "")
76:             }
77:             return nil
78: 
79:         case "text", "message":
80:             return dataString.isEmpty ? nil : .text(dataString)
81: 
82:         case "thinking":
83:             return dataString.isEmpty ? nil : .thinking(dataString)
84: 
85:         case "tool_call":
86:             if let dto = decodeJSON(ToolCallDTO.self, from: dataString) {
87:                 return .toolCall(
88:                     toolCallId: dto.toolCallId ?? "",
89:                     toolName: dto.toolName ?? "tool",
90:                     command: dto.command ?? ""
91:                 )
92:             }
93:             return .toolCall(toolCallId: "", toolName: "tool", command: dataString)
94: 
95:         case "tool_result":
96:             if let dto = decodeJSON(ToolResultDTO.self, from: dataString) {
97:                 return .toolResult(
98:                     toolCallId: dto.toolCallId ?? "",
99:                     toolName: dto.toolName ?? "tool",
100:                     result: dto.result ?? "",
101:                     status: dto.status ?? .completed
102:                 )
103:             }
104:             return .toolResult(toolCallId: "", toolName: "tool", result: dataString, status: .completed)
105: 
106:         case "permission_required":
107:             if let approval = decodeJSON(AgentPendingApproval.self, from: dataString) {
108:                 return .permissionRequired(approval)
109:             }
110:             return .error(String(localized: "agent.error.invalid_permission_event"))
111: 
112:         case "subagent":
113:             if let progress = decodeJSON(AgentSubagentProgress.self, from: dataString) {
114:                 return .subagent(progress)
115:             }
116:             return nil
117: 
118:         case "routing_notice":
119:             if let notice = decodeJSON(AgentRoutingNotice.self, from: dataString) {
120:                 return .routingNotice(notice)
121:             }
122:             return nil
123: 
124:         case "cancelled":
125:             let dto = decodeJSON(CancelledDTO.self, from: dataString)
126:             return .cancelled(runId: dto?.runId)
127: 
128:         case "error":
