140:     private func decodeJSON<T: Decodable>(_ type: T.Type, from raw: String) -> T? {
141:         let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
142:         guard !trimmed.isEmpty, let data = trimmed.data(using: .utf8) else {
143:             return nil
144:         }
145:         return try? decoder.decode(type, from: data)
146:     }
147: }
