9:     /** 两端统一的轮次数量、原始字节总量与纯图片消息说明。 */
10:     public static final int MAX_COUNT = 4;
11:     public static final int MAX_TOTAL_BYTES = 12 * 1024 * 1024;
12:     public static final int MAX_BASE64_CHARS = ((AgentImageAttachment.MAX_BYTES + 2) / 3) * 4;
13:     public static final String IMAGE_ONLY_PROMPT = "用户发送了一张图片，请识别并回应图片内容。";
14: 
15:     private static final byte[] PNG = {(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A};
16:     private static final byte[] JPEG = {(byte) 0xFF, (byte) 0xD8, (byte) 0xFF};
17:     private static final byte[] GIF = {'G', 'I', 'F', '8'};
18:     private static final byte[] RIFF = {'R', 'I', 'F', 'F'};
19:     private static final byte[] WEBP = {'W', 'E', 'B', 'P'};
20: 
21:     private AgentImages() { }
22: 
23:     /**
24:      * 校验并包装成模型可用的图片附件。
25:      *
26:      * @param data 图片原始字节
27:      * @return 图片附件
28:      * @throws IllegalArgumentException 格式不受支持、内容为空或超过大小上限
29:      */
30:     public static AgentImageAttachment parse(byte[] data) {
31:         if (data != null && data.length > AgentImageAttachment.MAX_BYTES) {
32:             throw new IllegalArgumentException("单张图片不能超过 10 MiB");
33:         }
34:         String mediaType = mediaType(data);
35:         if (mediaType == null) {
36:             throw new IllegalArgumentException("不支持的图片格式，仅支持 PNG、JPEG、WebP 与 GIF");
37:         }
38:         return new AgentImageAttachment(mediaType, data);
39:     }
40: 
41:     /** 返回文件头对应的媒体类型；无法识别时返回 null。 */
42:     static String mediaType(byte[] data) {
43:         if (data == null || data.length < 12) return null;
44:         if (startsWith(data, PNG)) return "image/png";
45:         if (startsWith(data, JPEG)) return "image/jpeg";
46:         if (startsWith(data, GIF) && (data[4] == '7' || data[4] == '9') && data[5] == 'a') return "image/gif";
47:         if (startsWith(data, RIFF) && startsWith(data, WEBP, 8)) return "image/webp";
48:         return null;
49:     }
50: 
51:     private static boolean startsWith(byte[] data, byte[] prefix) {
52:         return startsWith(data, prefix, 0);
53:     }
54: 
55:     private static boolean startsWith(byte[] data, byte[] prefix, int offset) {
56:         if (data.length < offset + prefix.length) return false;
57:         for (int i = 0; i < prefix.length; i++) {
58:             if (data[offset + i] != prefix[i]) return false;
59:         }
60:         return true;
61:     }
62: }

