                            viewModel.isRecordPickerOpen = false
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 8)
                    .transition(
                        reduceMotion
                            ? .opacity
                            : .move(edge: .bottom).combined(with: .opacity)
                    )
                } else if viewModel.isPlusMenuOpen {
                    HStack {
                        AgentPlusCategoryMenu(
