                return true
            }
            if entry.isImageOnly && content.hasPrefix("用户发送了一张图片") {
                return true
            }
            return false
        }) else {
            continue
        }
        usedUserIndices.insert(matchIndex)
        result[matchIndex].images = entry.images
    }
    return result
}

